// Afișarea numerelor de la 1 la n cu while
#include <iostream>
using namespace std;

int main() {
    int n, i = 1;
    cin >> n;
    while (i <= n) {
        cout << i << " ";
        i++;
    }
    return 0;
}

// Calculul sumei primelor n numere cu for
#include <iostream>
using namespace std;

int main() {
    int n, s = 0;
    cin >> n;
    for (int i = 1; i <= n; i++) {
        s += i;
    }
    cout << "Suma este: " << s;
    return 0;
}

lessons:
Schema generală de parcurgere a cifrelor:
`while (n > 0) {
    int c = n % 10; // prelucrează cifra c
    n = n / 10;
}`

Calculul oglinditului (inversului):
`int ogl = 0;
while (n > 0) {
    ogl = ogl * 10 + n % 10;
    n /= 10;
}`

