// Verificare palindrom
#include <iostream>
using namespace std;

int main() {
    int n, copie, ogl = 0;
    cin >> n;
    copie = n;
    while (n > 0) {
        ogl = ogl * 10 + n % 10;
        n /= 10;
    }
    if (copie == ogl) cout << "Este palindrom!";
    else cout << "Nu este palindrom!";
    return 0;
}

// Verificare dacă n este prim optim
#include <iostream>
using namespace std;

bool estePrim(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int d = 3; d * d <= n; d += 2) {
        if (n % d == 0) return false;
    }
    return true;
}

// CMMDC prin impartiri repetate
#include <iostream>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;
    while (b != 0) {
        int r = a % b;
        a = b;
        b = r;
    }
    cout << "CMMDC este: " << a;
    return 0;
}

