// Bubble Sort clasic
#include <iostream>
using namespace std;

int main() {
    int n = 5, v[5] = {5, 2, 8, 1, 3};
    bool sortat;
    do {
        sortat = true;
        for (int i = 0; i < n - 1; i++) {
            if (v[i] > v[i + 1]) {
                swap(v[i], v[i + 1]);
                sortat = false;
            }
        }
    } while (!sortat);
    return 0;
}
